/**
 * §8.3's actions. Split-by-saved-rule is deliberately absent: it needs
 * §5.4's split semantics and is recorded in BUILD-LOG as deferred, not
 * forgotten.
 */
sealed class Action {
    
    /**
     * Set the category: must be an assignable, unarchived LEAF.
     */
    data class SetCategory(
        val `categoryId`: kotlin.String) : Action()
        
    {
        

        companion object
    }
    
    data class AddTag(
        val `tag`: kotlin.String) : Action()
        
    {
        

        companion object
    }
    
    /**
     * Rename the merchant string going forward (canonicalisation: this is
     * how "SWIGGY " and "swiggy.in" become one name).
     */
    data class RenameMerchant(
        val `to`: kotlin.String) : Action()
        
    {
        

        companion object
    }
    
    /**
     * §8.3's flag-for-review, with the reason the rule gives.
     */
    data class Flag(
        val `reason`: kotlin.String) : Action()
        
    {
        

        companion object
    }
    
    /**
     * Terminal: this record is deliberately uncategorised. Stops rule
     * processing: explicit ignore beats later rules.
     */
    object Ignore : Action()
    
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAction : FfiConverterRustBuffer<Action>{
    override fun read(buf: ByteBuffer): Action {
        return when(buf.getInt()) {
            1 -> Action.SetCategory(
                FfiConverterString.read(buf),
                )
            2 -> Action.AddTag(
                FfiConverterString.read(buf),
                )
            3 -> Action.RenameMerchant(
                FfiConverterString.read(buf),
                )
            4 -> Action.Flag(
                FfiConverterString.read(buf),
                )
            5 -> Action.Ignore
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Action): ULong = when(value) {
        is Action.SetCategory -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`categoryId`)
            )
        }
        is Action.AddTag -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`tag`)
            )
        }
        is Action.RenameMerchant -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`to`)
            )
        }
        is Action.Flag -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
        is Action.Ignore -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: Action, buf: ByteBuffer) {
        when(value) {
            is Action.SetCategory -> {
                buf.putInt(1)
                FfiConverterString.write(value.`categoryId`, buf)
                Unit
            }
            is Action.AddTag -> {
                buf.putInt(2)
                FfiConverterString.write(value.`tag`, buf)
                Unit
            }
            is Action.RenameMerchant -> {
                buf.putInt(3)
                FfiConverterString.write(value.`to`, buf)
                Unit
            }
            is Action.Flag -> {
                buf.putInt(4)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is Action.Ignore -> {
                buf.putInt(5)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





