        val `minMinor`: kotlin.Long?, 
        val `maxMinor`: kotlin.Long?) : Condition()
        
    {
        

        companion object
    }
    
    data class Currency(
        val `code`: kotlin.String) : Condition()
        
    {
        

        companion object
    }
    
    /**
     * `day <= n` shapes (§8.3's `day <= 5`): the day-of-month test.
     */
    data class DayOfMonthMax(
        val `n`: kotlin.UInt) : Condition()
        
    {
        

        companion object
    }
    
    data class Direction(
        val `value`: kotlin.String) : Condition()
        
    {
        

        companion object
    }
    
    data class Account(
        val `value`: kotlin.String) : Condition()
        
    {
        

        companion object
    }
    
    data class Source(
        val `value`: kotlin.String) : Condition()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeCondition : FfiConverterRustBuffer<Condition>{
    override fun read(buf: ByteBuffer): Condition {
