sealed class CoreException: kotlin.Exception() {
    
    class UnknownCurrency(
        
        val v1: kotlin.String
        ) : CoreException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class MismatchedCurrencies(
        
        val `a`: kotlin.String, 
        
        val `b`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "a=${ `a` }, b=${ `b` }"
    }
    
    class Overflow(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * Malformed boundary input: bad hex, wrong lengths, empty strings.
     */
    class InvalidInput(
        
        val v1: kotlin.String
        ) : CoreException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class EmptyParticipants(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    class DuplicateParticipant(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    class UnknownParticipant(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    class NonPositiveWeight(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    class NegativeTotal(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    class PercentMismatch(
        
        val `gotBps`: kotlin.ULong
        ) : CoreException() {
        override val message
            get() = "gotBps=${ `gotBps` }"
    }
    
    class ExactSumMismatch(
        
        val `expected`: kotlin.Long, 
        
        val `got`: kotlin.Long
        ) : CoreException() {
        override val message
            get() = "expected=${ `expected` }, got=${ `got` }"
    }
    
    class DeltasExceedTotal(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    class LineAmountNonPositive(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    class EmptyLineAssignment(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    class TotalMismatch(
        
        val `expected`: kotlin.Long, 
        
        val `got`: kotlin.Long
        ) : CoreException() {
        override val message
            get() = "expected=${ `expected` }, got=${ `got` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): CoreException = FfiConverterTypeCoreError.lift(error_buf)
    }

    
}

