    override fun read(buf: ByteBuffer): CoreException {
        

        return when(buf.getInt()) {
            1 -> CoreException.UnknownCurrency(
                FfiConverterString.read(buf),
                )
            2 -> CoreException.MismatchedCurrencies(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            3 -> CoreException.Overflow()
            4 -> CoreException.InvalidInput(
                FfiConverterString.read(buf),
                )
            5 -> CoreException.EmptyParticipants()
            6 -> CoreException.DuplicateParticipant()
            7 -> CoreException.UnknownParticipant()
            8 -> CoreException.NonPositiveWeight()
