                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is CoreException.EmptyParticipants -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.DuplicateParticipant -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.UnknownParticipant -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.NonPositiveWeight -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.NegativeTotal -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.PercentMismatch -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterULong.allocationSize(value.`gotBps`)
            )
            is CoreException.ExactSumMismatch -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterLong.allocationSize(value.`expected`)
                + FfiConverterLong.allocationSize(value.`got`)
            )
            is CoreException.DeltasExceedTotal -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.LineAmountNonPositive -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.EmptyLineAssignment -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.TotalMismatch -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterLong.allocationSize(value.`expected`)
                + FfiConverterLong.allocationSize(value.`got`)
            )
        }
    }

    override fun write(value: CoreException, buf: ByteBuffer) {
        when(value) {
            is CoreException.UnknownCurrency -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is CoreException.MismatchedCurrencies -> {
                buf.putInt(2)
                FfiConverterString.write(value.`a`, buf)
                FfiConverterString.write(value.`b`, buf)
                Unit
            }
            is CoreException.Overflow -> {
                buf.putInt(3)
                Unit
            }
            is CoreException.InvalidInput -> {
                buf.putInt(4)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is CoreException.EmptyParticipants -> {
                buf.putInt(5)
                Unit
            }
            is CoreException.DuplicateParticipant -> {
                buf.putInt(6)
                Unit
            }
            is CoreException.UnknownParticipant -> {
                buf.putInt(7)
                Unit
            }
            is CoreException.NonPositiveWeight -> {
                buf.putInt(8)
                Unit
            }
            is CoreException.NegativeTotal -> {
                buf.putInt(9)
                Unit
            }
            is CoreException.PercentMismatch -> {
                buf.putInt(10)
                FfiConverterULong.write(value.`gotBps`, buf)
                Unit
            }
            is CoreException.ExactSumMismatch -> {
                buf.putInt(11)
                FfiConverterLong.write(value.`expected`, buf)
                FfiConverterLong.write(value.`got`, buf)
                Unit
            }
            is CoreException.DeltasExceedTotal -> {
                buf.putInt(12)
                Unit
            }
            is CoreException.LineAmountNonPositive -> {
                buf.putInt(13)
                Unit
            }
            is CoreException.EmptyLineAssignment -> {
                buf.putInt(14)
                Unit
            }
            is CoreException.TotalMismatch -> {
                buf.putInt(15)
                FfiConverterLong.write(value.`expected`, buf)
                FfiConverterLong.write(value.`got`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * The four layouts foreign sheets actually use. Explicitness beats
 * detection in a money path: the caller names the layout, core refuses
 * anything that does not match it exactly.
 */

enum class DateFormat {
    
    /**
     * `YYYY-MM-DD`, zero-padded, strictly 4-2-2.
     */
    ISO_YMD,
    /**
     * `M/D/YYYY`: US order, 1 to 2 digit month/day, 4-digit year.
     */
    US_MDY,
    /**
     * `D/M/YYYY`: day-first order, 1 to 2 digit day/month, 4-digit year.
     */
    EU_DMY,
    /**
     * `YYYY-MM-DD HH:MM:SS`, space separator, zero-padded, seconds
     * included (leap second 60 refused). Pinned from independent consumers
     * of BudgetBakers Wallet exports (2026); strictness is deliberate: an
     * unexpected shape must be REJECTED so the profile can be revisited,
     * never auto-guessed into a wrong timestamp.
     */
    ISO_YMD_HMS;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeDateFormat: FfiConverterRustBuffer<DateFormat> {
    override fun read(buf: ByteBuffer) = try {
        DateFormat.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: DateFormat) = 4UL

    override fun write(value: DateFormat, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





