            is StoreException.WrongKey -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is StoreException.NewerSchema -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterLong.allocationSize(value.`found`)
                + FfiConverterLong.allocationSize(value.`latest`)
            )
            is StoreException.Keystore -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is StoreException.InvalidInput -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is StoreException.Internal -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: StoreException, buf: ByteBuffer) {
        when(value) {
            is StoreException.Closed -> {
