                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is StoreException.WrongKey -> {
                buf.putInt(3)
                Unit
            }
            is StoreException.NewerSchema -> {
                buf.putInt(4)
                FfiConverterLong.write(value.`found`, buf)
                FfiConverterLong.write(value.`latest`, buf)
                Unit
            }
            is StoreException.Keystore -> {
                buf.putInt(5)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is StoreException.InvalidInput -> {
                buf.putInt(6)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is StoreException.Internal -> {
                buf.putInt(7)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





